    description: string | null;
    image: string | null;
    /**
     * The agent's advertised x402 resources index, always an absolute HTTP(S) URL. Non-null exactly when `specification` is `bazaar`; null for OpenAPI entries.
     */
    x402ResourcesUrl: string | null;
